-- title: Company
-- description: Employees, departments, managers, projects and salary history. Good for joins, self-joins, window functions and recursive queries.
--
-- Tables: departments, employees, projects, project_assignments, salary_history
-- This file is read-only sample data for the SQL Lab. The app copies it into a
-- practice database, so your experiments never change this file.
-- Generated by tools/generate_datasets.py

PRAGMA foreign_keys = ON;

CREATE TABLE departments (
    id       INTEGER PRIMARY KEY,
    name     TEXT NOT NULL UNIQUE,
    location TEXT NOT NULL,
    budget   INTEGER NOT NULL
);

CREATE TABLE employees (
    id            INTEGER PRIMARY KEY,
    first_name    TEXT NOT NULL,
    last_name     TEXT NOT NULL,
    email         TEXT UNIQUE,
    job_title     TEXT NOT NULL,
    department_id INTEGER REFERENCES departments (id),   -- NULL for contractors
    manager_id    INTEGER REFERENCES employees (id),     -- NULL for the CEO (nobody above)
    hire_date     TEXT NOT NULL,
    salary        INTEGER NOT NULL CHECK (salary > 0)    -- yearly salary
);

CREATE TABLE projects (
    id            INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    department_id INTEGER NOT NULL REFERENCES departments (id),
    start_date    TEXT NOT NULL,
    end_date      TEXT,                                 -- NULL = still running
    budget        INTEGER NOT NULL
);

CREATE TABLE project_assignments (
    employee_id INTEGER NOT NULL REFERENCES employees (id),
    project_id  INTEGER NOT NULL REFERENCES projects (id),
    role        TEXT NOT NULL,
    hours       INTEGER NOT NULL,
    PRIMARY KEY (employee_id, project_id)
);

CREATE TABLE salary_history (
    id             INTEGER PRIMARY KEY,
    employee_id    INTEGER NOT NULL REFERENCES employees (id),
    effective_date TEXT NOT NULL,
    salary         INTEGER NOT NULL
);





